    }

    if (lastTop <= segTop) {
      const span = Math.max(1, segTop - segBottom);
      const rawProgress = (segTop - lastTop) / span;
      const c = Math.max(0, Math.min(1, rawProgress));
      const progress = c * c * (3 - 2 * c);
