          #trackRef
          class="flex items-stretch will-change-transform"
          [style.gap.px]="itemGap"
          style="padding-left: max(1.5rem, calc((100vw - 1280px) / 2 + 1.5rem)); padding-right: max(1.5rem, calc((100vw - 1280px) / 2 + 1.5rem));"
        >
