  selector: 'exhuma-auto-grid',
  standalone: true,
  imports: [CommonModule],
  template: `
    <div
      class="exhuma-auto-grid w-full {{ className() }}"
      [style.display]="'grid'"
      [style.gridTemplateColumns]="gridTemplateColumns()"
      [style.gap]="gapVal()"
      [style.alignItems]="alignItems()"
    >
      <ng-content />
    </div>
  `,
