import React, { useState, useRef, useEffect } from 'react';
import { View, Text, Pressable, Animated, StyleSheet, LayoutChangeEvent } from 'react-native';

export interface TabItem {
  id: string;
  label: string;
}

export interface MorphingTabsProps {
  items: TabItem[];
  value?: string;
  onValueChange?: (id: string) => void;
  variant?: 'pill' | 'underline' | 'glow';
  size?: 'sm' | 'md' | 'lg';
}

export const MorphingTabs: React.FC<MorphingTabsProps> = ({
  items,
  value,
  onValueChange,
  variant = 'pill',
  size = 'md',
}) => {
  const [activeTab, setActiveTab] = useState(value || items[0]?.id || '');
  const [layouts, setLayouts] = useState<Record<string, { x: number; width: number; height: number }>>({});

  const translateX = useRef(new Animated.Value(0)).current;
  const indicatorWidth = useRef(new Animated.Value(0)).current;

  const onTabLayout = (id: string, e: LayoutChangeEvent) => {
    const { x, width, height } = e.nativeEvent.layout;
    setLayouts((prev) => {
      const next = { ...prev, [id]: { x, width, height } };
      if (id === activeTab) {
        animateTo(x, width);
      }
      return next;
    });
  };

  const animateTo = (x: number, width: number) => {
    Animated.parallel([
      Animated.spring(translateX, {
        toValue: x,
        useNativeDriver: false,
        tension: 78,
        friction: 20,
      }),
      Animated.spring(indicatorWidth, {
        toValue: width,
        useNativeDriver: false,
        tension: 78,
        friction: 20,
      }),
    ]).start();
  };

  const handleSelect = (id: string) => {
    setActiveTab(id);
    onValueChange?.(id);
    const layout = layouts[id];
    if (layout) {
      animateTo(layout.x, layout.width);
    }
  };

  useEffect(() => {
    const layout = layouts[activeTab];
    if (layout) {
      animateTo(layout.x, layout.width);
    }
  }, [variant, size]);

  const padH = size === 'sm' ? 12 : size === 'lg' ? 24 : 16;
  const padV = size === 'sm' ? 6 : size === 'lg' ? 12 : 8;
  const fontSize = size === 'sm' ? 12 : size === 'lg' ? 16 : 14;

  return (
    <View style={styles.container}>
      <View style={[styles.list, variant === 'underline' && styles.listUnderline]}>
        <Animated.View
          style={[
            styles.indicator,
            variant === 'underline' && styles.indicatorUnderline,
            variant === 'glow' && styles.indicatorGlow,
            {
              transform: [{ translateX }],
              width: indicatorWidth,
            },
          ]}
        />
        {items.map((item) => {
          const isSelected = activeTab === item.id;
          return (
            <Pressable
              key={item.id}
              onLayout={(e) => onTabLayout(item.id, e)}
              onPress={() => handleSelect(item.id)}
              style={[styles.tab, { paddingHorizontal: padH, paddingVertical: padV }]}
            >
              <Text
                style={[
                  styles.tabText,
                  { fontSize },
                  isSelected && (variant === 'underline' ? styles.tabTextUnderlineActive : styles.tabTextActive),
                ]}
              >
                {item.label}
              </Text>
            </Pressable>
          );
        })}
      </View>
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    flexDirection: 'column',
  },
  list: {
    position: 'relative',
    flexDirection: 'row',
    alignItems: 'center',
    backgroundColor: '#f4f4f5',
    borderRadius: 16,
    padding: 6,
  },
  listUnderline: {
    backgroundColor: 'transparent',
    borderBottomWidth: 1,
    borderBottomColor: '#e4e4e7',
    borderRadius: 0,
    padding: 0,
  },
  indicator: {
    position: 'absolute',
    top: 6,
    left: 0,
    bottom: 6,
    backgroundColor: '#ffffff',
    borderRadius: 12,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 1 },
    shadowOpacity: 0.1,
    shadowRadius: 2,
    elevation: 2,
  },
  indicatorUnderline: {
    top: undefined,
    bottom: 0,
    height: 2,
    backgroundColor: '#6366f1',
    borderRadius: 1,
    shadowColor: '#6366f1',
    shadowOpacity: 0.5,
    shadowRadius: 4,
  },
  indicatorGlow: {
    backgroundColor: '#ffffff',
    borderColor: '#6366f1',
    borderWidth: 1,
    shadowColor: '#6366f1',
    shadowOpacity: 0.4,
    shadowRadius: 8,
  },
  tab: {
    zIndex: 1,
  },
  tabText: {
    color: '#71717a',
    fontWeight: '500',
  },
  tabTextActive: {
    color: '#18181b',
    fontWeight: '700',
  },
  tabTextUnderlineActive: {
    color: '#6366f1',
    fontWeight: '700',
  },
});

export default MorphingTabs;

