import 'package:flutter/material.dart';

class AccordionItemData {
  final String value;
  final String title;
  final String content;

  const AccordionItemData({
    required this.value,
    required this.title,
    required this.content,
  });
}

class ExhumaAccordion extends StatefulWidget {
  final List<AccordionItemData> items;
  final bool multiple;
  final bool collapsible;
  final double gap;
  final bool bordered;
  final bool showNumbers;
  final bool showIcon;
  final Duration duration;

  const ExhumaAccordion({
    super.key,
    required this.items,
    this.multiple = false,
    this.collapsible = true,
    this.gap = 12.0,
    this.bordered = true,
    this.showNumbers = true,
    this.showIcon = true,
    this.duration = const Duration(milliseconds: 300),
  });

  @override
  State<ExhumaAccordion> createState() => _ExhumaAccordionState();
}

class _ExhumaAccordionState extends State<ExhumaAccordion> {
  late Set<String> _expandedValues;

  @override
  void initState() {
    super.initState();
    _expandedValues = widget.items.isNotEmpty ? {widget.items.first.value} : {};
  }

  void _toggle(String val) {
    setState(() {
      if (_expandedValues.contains(val)) {
        if (widget.collapsible || _expandedValues.length > 1) {
          _expandedValues.remove(val);
        }
      } else {
        if (!widget.multiple) {
          _expandedValues.clear();
        }
        _expandedValues.add(val);
      }
    });
  }

  @override
  Widget build(BuildContext context) {
    return Column(
      children: [
        for (int i = 0; i < widget.items.length; i++) ...[
          _buildItem(widget.items[i], i),
          if (i < widget.items.length - 1) SizedBox(height: widget.gap),
        ],
      ],
    );
  }

  Widget _buildItem(AccordionItemData item, int index) {
    final isOpen = _expandedValues.contains(item.value);
    final theme = Theme.of(context);

    return Container(
      decoration: BoxDecoration(
        color: theme.cardColor,
        borderRadius: BorderRadius.circular(16),
        border: widget.bordered
            ? Border.all(
                color: isOpen
                    ? theme.colorScheme.primary.withValues(alpha: 0.5)
                    : theme.dividerColor.withValues(alpha: 0.3),
                width: isOpen ? 1.5 : 1.0,
              )
            : null,
        boxShadow: isOpen
            ? [
                BoxShadow(
                  color: Colors.black.withValues(alpha: 0.05),
                  blurRadius: 10,
                  offset: const Offset(0, 4),
                )
              ]
            : null,
      ),
      child: Column(
        children: [
          InkWell(
            onTap: () => _toggle(item.value),
            borderRadius: BorderRadius.circular(16),
            child: Padding(
              padding: const EdgeInsets.symmetric(horizontal: 20, vertical: 16),
              child: Row(
                children: [
                  if (widget.showNumbers) ...[
                    Text(
                      '${(index + 1).toString().padLeft(2, '0')}',
                      style: TextStyle(
                        fontFamily: 'monospace',
                        fontWeight: FontWeight.bold,
                        fontSize: 12,
                        color: theme.colorScheme.primary,
                      ),
                    ),
                    const SizedBox(width: 14),
                  ],
                  Expanded(
                    child: Text(
                      item.title,
                      style: theme.textTheme.titleMedium?.copyWith(
                        fontWeight: FontWeight.w600,
                      ),
                    ),
                  ),
                  if (widget.showIcon)
                    SizedBox(
                      width: 24,
                      height: 24,
                      child: Stack(
                        alignment: Alignment.center,
                        children: [
                          Container(
                            width: 14,
                            height: 2,
                            decoration: BoxDecoration(
                              color: theme.colorScheme.primary,
                              borderRadius: BorderRadius.circular(2),
                            ),
                          ),
                          AnimatedRotation(
                            turns: isOpen ? 0.0 : 0.25,
                            duration: widget.duration,
                            child: Container(
                              width: 2,
                              height: 14,
                              decoration: BoxDecoration(
                                color: theme.colorScheme.primary,
                                borderRadius: BorderRadius.circular(2),
                              ),
                            ),
                          ),
                        ],
                      ),
                    ),
                ],
              ),
            ),
          ),
          AnimatedSize(
            duration: widget.duration,
            curve: Curves.easeInOut,
            child: isOpen
                ? Padding(
                    padding: const EdgeInsets.fromLTRB(20, 0, 20, 20),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Divider(
                          color: theme.dividerColor.withValues(alpha: 0.2),
                          height: 1,
                        ),
                        const SizedBox(height: 14),
                        Text(
                          item.content,
                          style: theme.textTheme.bodyMedium?.copyWith(
                            color: theme.textTheme.bodyMedium?.color?.withValues(alpha: 0.7),
                            height: 1.5,
                          ),
                        ),
                      ],
                    ),
                  )
                : const SizedBox.shrink(),
          ),
        ],
      ),
    );
  }
}

