      e.preventDefault();
      nextIndex = (currentIndex - 1 + count) % count;
    } else if (e.key === 'Home') {
      e.preventDefault();
      nextIndex = 0;
    } else if (e.key === 'End') {
      e.preventDefault();
      nextIndex = count - 1;
    }

    if (nextIndex !== currentIndex) {
      const el = document.getElementById(`${this.baseId}-trigger-${this.items()[nextIndex].value}`);
      el?.focus();
    }
  }
}

