import React, { useState } from 'react';
import {
  View,
  Text,
  Pressable,
  LayoutAnimation,
  Platform,
  UIManager,
  StyleSheet,
} from 'react-native';

if (Platform.OS === 'android' && UIManager.setLayoutAnimationEnabledExperimental) {
  UIManager.setLayoutAnimationEnabledExperimental(true);
}

export interface AccordionItemData {
  value: string;
  title: string;
  content: string;
}

export interface AccordionProps {
  items: AccordionItemData[];
  mode?: 'single' | 'multiple';
  collapsible?: boolean;
  gap?: number;
  bordered?: boolean;
  showNumbers?: boolean;
  showIcon?: boolean;
}

export const Accordion: React.FC<AccordionProps> = ({
  items,
  mode = 'single',
  collapsible = true,
  gap = 12,
  bordered = true,
  showNumbers = true,
  showIcon = true,
}) => {
  const [activeValues, setActiveValues] = useState<string[]>([items[0]?.value ?? '']);

  const toggle = (val: string) => {
    LayoutAnimation.configureNext(LayoutAnimation.Presets.easeInEaseOut);
    const isOpen = activeValues.includes(val);

    if (isOpen) {
      if (collapsible || activeValues.length > 1) {
        setActiveValues(activeValues.filter((v) => v !== val));
      }
    } else {
      if (mode === 'single') {
        setActiveValues([val]);
      } else {
        setActiveValues([...activeValues, val]);
      }
    }
  };

  return (
    <View style={[styles.root, { gap }]}>
      {items.map((item, idx) => {
        const isOpen = activeValues.includes(item.value);
        return (
          <View
            key={item.value}
            style={[
              styles.item,
              bordered && styles.bordered,
              isOpen && bordered && styles.itemActive,
            ]}
          >
            <Pressable
              onPress={() => toggle(item.value)}
              style={styles.trigger}
              accessibilityRole="button"
              accessibilityState={{ expanded: isOpen }}
            >
              <View style={styles.titleContainer}>
                {showNumbers && (
                  <Text style={styles.badge}>
                    {String(idx + 1).padStart(2, '0')}
                  </Text>
                )}
                <Text style={styles.title}>{item.title}</Text>
              </View>

              {showIcon && (
                <View style={styles.iconContainer}>
                  <View style={[styles.bar, styles.barH]} />
                  <View
                    style={[
                      styles.bar,
                      styles.barV,
                      isOpen && { transform: [{ rotate: '0deg' }] },
                    ]}
                  />
                </View>
              )}
            </Pressable>

            {isOpen && (
              <View style={styles.contentContainer}>
                <View style={styles.contentDivider} />
                <Text style={styles.contentText}>{item.content}</Text>
              </View>
            )}
          </View>
        );
      })}
    </View>
  );
};

const styles = StyleSheet.create({
