          pullY *= scale;
        }
      }
      this.target.x = pullX;
      this.target.y = pullY;
    }

    this.isHovered = true;
    this.startRaf();
  }

  onPointerLeave() {
    this.isHovered = false;
    this.target.x = 0;
    this.target.y = 0;
    this.startRaf();
  }

