import React, { useRef, useState } from 'react';
import { View, Text, StyleSheet, Animated, PanResponder, type ViewStyle } from 'react-native';

export interface CursorTooltipProps {
  content?: string;
  springDamping?: number;
  direction?: string;
  offsetX?: number;
  offsetY?: number;
  variant?: 'frosted' | 'accent' | 'dark' | 'minimal' | 'glow';
  style?: ViewStyle;
  children?: React.ReactNode;
}

export const CursorTooltip: React.FC<CursorTooltipProps> = ({
  content = 'Explore Showcase',
  springDamping = 20,
  direction = 'bottom-right',
  offsetX = 16,
  offsetY = 16,
  variant = 'frosted',
  style,
  children,
}) => {
  const pan = useRef(new Animated.ValueXY({ x: 0, y: 0 })).current;
  const [active, setActive] = useState(false);

  const panResponder = useRef(
    PanResponder.create({
      onStartShouldSetPanResponder: () => true,
      onPanResponderGrant: (evt) => {
        setActive(true);
        pan.setValue({ x: evt.nativeEvent.locationX + offsetX, y: evt.nativeEvent.locationY + offsetY });
      },
      onPanResponderMove: (evt) => {
        Animated.spring(pan, {
          toValue: { x: evt.nativeEvent.locationX + offsetX, y: evt.nativeEvent.locationY + offsetY },
          bounciness: 0,
          speed: springDamping,
          useNativeDriver: false,
        }).start();
      },
      onPanResponderRelease: () => {
        setActive(false);
      },
    })
  ).current;

  return (
    <View style={[styles.container, style]} {...panResponder.panHandlers}>
      {children}
      {active && (
        <Animated.View
          style={[
            styles.badge,
            variant === 'accent' ? styles.accentBadge : styles.frostedBadge,
            { left: pan.x, top: pan.y },
          ]}
        >
          <Text style={variant === 'accent' ? styles.accentText : styles.frostedText}>{content}</Text>
        </Animated.View>
      )}
    </View>
  );
};

const styles = StyleSheet.create({
  container: {
    position: 'relative',
  },
  badge: {
    position: 'absolute',
    paddingHorizontal: 12,
    paddingVertical: 6,
    borderRadius: 12,
    shadowColor: '#000',
    shadowOpacity: 0.15,
    shadowRadius: 8,
    elevation: 4,
  },
  frostedBadge: {
    backgroundColor: 'rgba(255, 255, 255, 0.9)',
    borderColor: 'rgba(0, 0, 0, 0.1)',
    borderWidth: 1,
  },
  frostedText: {
    color: '#09090b',
    fontSize: 12,
    fontWeight: '600',
  },
  accentBadge: {
    backgroundColor: '#6366f1',
  },
  accentText: {
    color: '#ffffff',
    fontSize: 12,
    fontWeight: 'bold',
  },
});

