import 'dart:math' as math;
import 'package:flutter/material.dart';

class ExhumaCursorTooltip extends StatefulWidget {
  final Widget child;
  final String content;
  final double springDamping;
  final String direction;
  final double offsetX;
  final double offsetY;
  final String variant;
  final double collisionPadding;

  const ExhumaCursorTooltip({
    Key? key,
    required this.child,
    this.content = 'Explore Showcase',
    this.springDamping = 20.0,
    this.direction = 'bottom-right',
    this.offsetX = 16.0,
    this.offsetY = 16.0,
    this.variant = 'frosted',
    this.collisionPadding = 12.0,
  }) : super(key: key);

  @override
  State<ExhumaCursorTooltip> createState() => _ExhumaCursorTooltipState();
}

class _ExhumaCursorTooltipState extends State<ExhumaCursorTooltip> with SingleTickerProviderStateMixin {
  Offset _target = const Offset(-9999, -9999);
  Offset _current = const Offset(-9999, -9999);
  bool _isHovered = false;
  late AnimationController _controller;

  @override
  void initState() {
    super.initState();
    _controller = AnimationController(
      vsync: this,
      duration: const Duration(seconds: 1),
    )..addListener(_tick);
  }

  void _tick() {
    if (!_isHovered) return;
    final double dt = 0.016;
    final double lambda = widget.springDamping;
    final double factor = 1.0 - math.exp(-lambda * dt);

    final double nextX = _current.dx + (_target.dx - _current.dx) * factor;
    final double nextY = _current.dy + (_target.dy - _current.dy) * factor;

    setState(() {
      _current = Offset(nextX, nextY);
    });

    if ((_target - _current).distance > 0.2) {
      _controller.forward(from: 0.0);
    }
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return MouseRegion(
      onEnter: (event) {
        setState(() {
          _isHovered = true;
          _target = event.localPosition + Offset(widget.offsetX, widget.offsetY);
          _current = _target;
        });
        _controller.forward(from: 0.0);
      },
      onHover: (event) {
        setState(() {
          _target = event.localPosition + Offset(widget.offsetX, widget.offsetY);
        });
        if (!_controller.isAnimating) {
          _controller.forward(from: 0.0);
        }
      },
      onExit: (_) {
        setState(() {
          _isHovered = false;
          _target = const Offset(-9999, -9999);
        });
      },
      child: Stack(
        clipBehavior: Clip.none,
        children: [
          widget.child,
          if (_isHovered)
            Positioned(
              left: _current.dx,
              top: _current.dy,
              child: IgnorePointer(
                child: Container(
                  padding: const EdgeInsets.symmetric(horizontal: 12, vertical: 6),
                  decoration: BoxDecoration(
                    color: widget.variant == 'accent' ? Theme.of(context).primaryColor : Colors.black87,
                    borderRadius: BorderRadius.circular(12),
                    boxShadow: const [
                      BoxShadow(
                        color: Colors.black26,
                        blurRadius: 8,
                        offset: Offset(0, 4),
                      ),
                    ],
                  ),
                  child: Text(
                    widget.content,
                    style: const TextStyle(
                      color: Colors.white,
                      fontSize: 12,
                      fontWeight: FontWeight.w600,
                    ),
                  ),
                ),
              ),
            ),
        ],
      ),
    );
  }
}

